-- Public website content is distinct from private customer workspace records.
create table private.website_posts(
 id uuid primary key default gen_random_uuid(),slug text not null unique,
 draft jsonb not null,published jsonb,status text not null default 'draft' check(status in('draft','published','archived')),
 revision integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),first_published_at timestamptz,published_updated_at timestamptz,
 check(slug~'^[a-z0-9]+(-[a-z0-9]+)*$'and length(slug)<=120)
);
alter table private.website_posts enable row level security;
revoke all on private.website_posts from public,anon,authenticated,service_role,console_backend;
create table private.career_enquiries(
 id uuid primary key,request_hash text not null,ip_hash text not null,email_hash text not null,
 full_name text not null,email text not null,interest text not null,location text not null default '',portfolio text not null default '',message text not null,
 consent_at timestamptz not null default now(),status text not null default 'new'check(status in('new','reviewing','contacted','archived')),revision integer not null default 1,created_at timestamptz not null default now()
);
alter table private.career_enquiries enable row level security;
revoke all on private.career_enquiries from public,anon,authenticated,service_role,console_backend;
create index career_enquiries_created_idx on private.career_enquiries(created_at desc);
create index career_enquiries_ip_idx on private.career_enquiries(ip_hash,created_at);
create index career_enquiries_email_idx on private.career_enquiries(email_hash,created_at);
create table private.career_notifications(
 id uuid primary key default gen_random_uuid(),enquiry_id uuid not null unique references private.career_enquiries(id),
 status text not null default 'queued'check(status in('queued','sending','accepted','failed')),attempts integer not null default 0,
 lease uuid,claimed_at timestamptz,next_attempt timestamptz not null default now(),accepted_at timestamptz
);
alter table private.career_notifications enable row level security;
revoke all on private.career_notifications from public,anon,authenticated,service_role,console_backend;
create table private.website_dispatch_config(singleton boolean primary key default true check(singleton),token text not null);
alter table private.website_dispatch_config enable row level security;
revoke all on private.website_dispatch_config from public,anon,authenticated,service_role,console_backend;
insert into private.website_dispatch_config(token)values(replace(gen_random_uuid()::text,'-','')||replace(gen_random_uuid()::text,'-',''));
insert into public.staff_permissions(role,page,access)values('owner','blog','full'),('owner','careers','full')on conflict(role,page)do update set access=excluded.access;

create function private.website_valid_post(d jsonb)returns boolean language plpgsql immutable set search_path='' as $$
declare s jsonb;p jsonb;q jsonb;dt date;begin
 if jsonb_typeof(d)is distinct from 'object'or not(d?&array['slug','title','description','author','published','sections'])or octet_length(d::text)>180000 then return false;end if;
 if d->>'slug'!~'^[a-z0-9]+(-[a-z0-9]+)*$'or length(d->>'slug')not between 1 and 120 or length(btrim(d->>'title'))not between 1 and 180 or length(btrim(d->>'description'))not between 1 and 500 or length(btrim(d->>'author'))not between 1 and 100 or d->>'published'!~'^\d{4}-\d{2}-\d{2}$'then return false;end if;
 if exists(select 1 from jsonb_each(d)e where e.key in('slug','title','description','author','published')and jsonb_typeof(e.value)<>'string')then return false;end if;
 dt:=(d->>'published')::date;
 if jsonb_typeof(d->'sections')is distinct from 'array'or jsonb_array_length(d->'sections')not between 1 and 40 then return false;end if;
 for s in select value from jsonb_array_elements(d->'sections')loop
  if jsonb_typeof(s)is distinct from 'object'or jsonb_typeof(s->'heading')is distinct from 'string'or length(btrim(s->>'heading'))not between 1 and 200 or s->>'heading'is null or jsonb_typeof(s->'paragraphs')is distinct from 'array'or jsonb_array_length(s->'paragraphs')not between 1 and 30 then return false;end if;
  for p in select value from jsonb_array_elements(s->'paragraphs')loop if jsonb_typeof(p)<>'string'or length(btrim(p#>>'{}'))not between 1 and 10000 then return false;end if;end loop;
 end loop;
 if d?'template'and(jsonb_typeof(d->'template')<>'string'or length(d->>'template')>30000)then return false;end if;
 if d?'faq'then
  if jsonb_typeof(d->'faq')<>'array'or jsonb_array_length(d->'faq')>20 then return false;end if;
  for q in select value from jsonb_array_elements(d->'faq')loop if jsonb_typeof(q)is distinct from 'object'or jsonb_typeof(q->'question')is distinct from 'string'or jsonb_typeof(q->'answer')is distinct from 'string'or q->>'question'is null or q->>'answer'is null or length(btrim(q->>'question'))not between 1 and 300 or length(btrim(q->>'answer'))not between 1 and 5000 then return false;end if;end loop;
 end if;return true;
exception when others then return false;end $$;
revoke all on function private.website_valid_post(jsonb)from public,anon,authenticated,service_role,console_backend;
create function private.website_blog(p_slug text default null)returns jsonb language sql stable security definer set search_path=''as $$
 select case when p_slug is null then coalesce((select jsonb_agg(published||jsonb_build_object('modified',coalesce(published_updated_at,first_published_at,updated_at)::date::text)order by published->>'published'desc,slug)from private.website_posts where status='published'),'[]'::jsonb)else(select published||jsonb_build_object('modified',coalesce(published_updated_at,first_published_at,updated_at)::date::text)from private.website_posts where status='published'and slug=p_slug)end
$$;
revoke all on function private.website_blog(text)from public,anon,authenticated,service_role,console_backend;
grant execute on function private.website_blog(text)to anon,authenticated;
create function public.website_blog(p_slug text default null)returns jsonb language sql stable security invoker set search_path=''as $$select private.website_blog(p_slug)$$;
revoke all on function public.website_blog(text)from public,anon,authenticated,service_role;
grant execute on function public.website_blog(text)to anon,authenticated;

create function private.console_website(p_action text,p_id uuid default null,p_revision integer default null,p_data jsonb default '{}')returns jsonb language plpgsql security definer set search_path=''as $$
declare gate jsonb;staff_role text;row private.website_posts;item private.career_enquiries;page_name text;result jsonb;search text;offset_n integer;begin
 gate:=private.console_request('self','',0);if not coalesce((gate->>'ok')::boolean,false)then return gate;end if;
 page_name:=case when p_action like 'career_%'then 'careers'else 'blog'end;
 select role into staff_role from public.staff_members where user_id=auth.uid()and active;
 if staff_role is distinct from 'owner'or not exists(select 1 from public.staff_permissions where role=staff_role and page=page_name and access='full')then
 insert into public.staff_activity_log(staff_user_id,action,outcome)values(auth.uid(),page_name,'denied');return jsonb_build_object('ok',false,'code','access_denied');end if;
 if p_action in('list','career_list')then
  search:=left(coalesce(p_data->>'search',''),80);offset_n:=greatest(0,least(coalesce((p_data->>'page')::integer,0),10000))*20;
  if p_action='list'then select jsonb_build_object('rows',coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb))into result from(select id,slug,draft->>'title'as title,status,revision,updated_at,published is not null and draft<>published as has_changes from private.website_posts where (search=''or position(lower(search)in lower(draft->>'title'))>0)order by updated_at desc,id limit 21 offset offset_n)t;
  else select jsonb_build_object('rows',coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb))into result from(select c.id,c.full_name,c.email,c.interest,c.location,c.status,c.revision,c.created_at,n.status as notification_status from private.career_enquiries c left join private.career_notifications n on n.enquiry_id=c.id where (search=''or position(lower(search)in lower(c.full_name||' '||c.email||' '||c.interest))>0)and(coalesce(p_data->>'status','')=''or c.status=p_data->>'status')order by c.created_at desc,c.id limit 21 offset offset_n)t;end if;
 elsif p_action='career_get'then
  select to_jsonb(c)-'ip_hash'-'email_hash'-'request_hash'||jsonb_build_object('notification_status',n.status)into result from private.career_enquiries c left join private.career_notifications n on n.enquiry_id=c.id where c.id=p_id;
 elsif p_action='career_status'then
  if p_data->>'status'not in('new','reviewing','contacted','archived')or p_data->>'status'is null then return jsonb_build_object('ok',false,'code','invalid_input');end if;
  select *into item from private.career_enquiries where id=p_id for update;if not found then return jsonb_build_object('ok',false,'code','not_found');end if;
  if item.revision is distinct from p_revision then return jsonb_build_object('ok',false,'code','conflict');end if;
  update private.career_enquiries set status=p_data->>'status',revision=revision+1 where id=p_id returning jsonb_build_object('id',id,'revision',revision)into result;
 elsif p_action='career_retry'then
  update private.career_notifications set status='queued',attempts=0,next_attempt=now(),lease=null where enquiry_id=p_id and status='failed';result:='{"queued":true}'::jsonb;
 elsif p_action='get'then select to_jsonb(p)into result from private.website_posts p where id=p_id;
 elsif p_action in('save','publish','unpublish','archive')then
  if p_action='save'and not private.website_valid_post(p_data)then return jsonb_build_object('ok',false,'code','invalid_input');end if;
  if p_id is null then
   if p_action<>'save'then return jsonb_build_object('ok',false,'code','invalid_input');end if;
   insert into private.website_posts(slug,draft)values(p_data->>'slug',p_data)returning *into row;
  else
   select *into row from private.website_posts where id=p_id for update;if not found then return jsonb_build_object('ok',false,'code','not_found');end if;
   if row.revision is distinct from p_revision then return jsonb_build_object('ok',false,'code','conflict');end if;
   if p_action='save'then
    if row.first_published_at is not null and row.slug<>p_data->>'slug'then return jsonb_build_object('ok',false,'code','slug_locked');end if;
    update private.website_posts set draft=p_data,slug=p_data->>'slug',revision=revision+1,updated_at=now()where id=p_id returning *into row;
   elsif p_action='publish'then
    if not private.website_valid_post(row.draft)or(row.draft->>'published')::date>current_date then return jsonb_build_object('ok',false,'code','invalid_input');end if;
    update private.website_posts set published=draft,status='published',first_published_at=coalesce(first_published_at,now()),published_updated_at=now(),revision=revision+1,updated_at=now()where id=p_id returning *into row;
   else update private.website_posts set published=null,status=case when p_action='archive'then 'archived'else 'draft'end,revision=revision+1,updated_at=now()where id=p_id returning *into row;
   end if;
  end if;result:=to_jsonb(row);
 else return jsonb_build_object('ok',false,'code','invalid_input');end if;
 insert into public.staff_activity_log(staff_user_id,action,outcome,target_type,target_id)values(auth.uid(),'website_'||p_action,'allowed',page_name,p_id);
 return jsonb_build_object('ok',true,'data',result);
exception when unique_violation then return jsonb_build_object('ok',false,'code','slug_exists');when invalid_text_representation or numeric_value_out_of_range then return jsonb_build_object('ok',false,'code','invalid_input');end$$;
revoke all on function private.console_website(text,uuid,integer,jsonb)from public,anon,authenticated,service_role,console_backend;
grant execute on function private.console_website(text,uuid,integer,jsonb)to authenticated;
create function public.console_website(p_action text,p_id uuid default null,p_revision integer default null,p_data jsonb default '{}')returns jsonb language sql security invoker set search_path=''as $$select private.console_website(p_action,p_id,p_revision,p_data)$$;
revoke all on function public.console_website(text,uuid,integer,jsonb)from public,anon,authenticated,service_role;
grant execute on function public.console_website(text,uuid,integer,jsonb)to authenticated;

-- Service-only intake and email outbox. Public callers never read submissions.
create function private.website_careers_service(p_action text,p_id uuid default null,p_data jsonb default '{}')returns jsonb language plpgsql security definer set search_path=''as $$
declare prior private.career_enquiries;payload jsonb;job private.career_notifications;results jsonb:='[]';begin
 if p_action='create'then
  payload:=p_data->'application';
  if p_id is null or jsonb_typeof(payload)is distinct from 'object'or length(p_data->>'ip_hash')<>64 or length(p_data->>'email_hash')<>64 or length(p_data->>'request_hash')<>64 or p_data->>'ip_hash'is null or p_data->>'email_hash'is null or p_data->>'request_hash'is null then return jsonb_build_object('ok',false,'code','invalid_input');end if;
  if length(btrim(payload->>'full_name'))not between 1 and 100 or payload->>'full_name'is null or payload->>'email'!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'or length(payload->>'email')>254 or payload->>'email'is null or payload->>'interest'not in('Engineering','Design','Product','Marketing','Operations','Other')or payload->>'interest'is null or length(payload->>'location')>120 or length(payload->>'portfolio')>500 or(payload->>'portfolio'<>''and payload->>'portfolio'!~'^https://[^/@[:space:]]+([/?#][^[:space:]]*)?$')or length(btrim(payload->>'message'))not between 1 and 2000 or payload->>'message'is null or payload->>'consent'is distinct from 'true'then return jsonb_build_object('ok',false,'code','invalid_input');end if;
  perform pg_advisory_xact_lock(hashtextextended('career:'||(p_data->>'ip_hash'),0));perform pg_advisory_xact_lock(hashtextextended('career-email:'||(p_data->>'email_hash'),0));
  select *into prior from private.career_enquiries where id=p_id;if found then return jsonb_build_object('ok',prior.request_hash=p_data->>'request_hash','code',case when prior.request_hash=p_data->>'request_hash'then 'accepted'else 'invalid_input'end);end if;
  if(select count(*)from private.career_enquiries where ip_hash=p_data->>'ip_hash'and created_at>now()-interval '1 hour')>=3 or(select count(*)from private.career_enquiries where email_hash=p_data->>'email_hash'and created_at>now()-interval '1 day')>=2 then return jsonb_build_object('ok',false,'code','rate_limited');end if;
  insert into private.career_enquiries(id,request_hash,ip_hash,email_hash,full_name,email,interest,location,portfolio,message)values(p_id,p_data->>'request_hash',p_data->>'ip_hash',p_data->>'email_hash',btrim(payload->>'full_name'),lower(btrim(payload->>'email')),payload->>'interest',coalesce(payload->>'location',''),coalesce(payload->>'portfolio',''),btrim(payload->>'message'));
  insert into private.career_notifications(enquiry_id)values(p_id);return '{"ok":true,"code":"accepted"}'::jsonb;
 elsif p_action='claim'then
  if p_data?'dispatch_hash'and not exists(select 1 from private.website_dispatch_config where encode(sha256(convert_to(token,'UTF8')),'hex')=p_data->>'dispatch_hash')then return '{"ok":false,"code":"access_denied"}'::jsonb;end if;
  update private.career_notifications set status='failed',lease=null where status='sending'and claimed_at<now()-interval '15 minutes'and attempts>=5;
  for job in select *from private.career_notifications where(status='queued'and next_attempt<=now()or status='sending'and claimed_at<now()-interval '15 minutes')and attempts<5 order by next_attempt for update skip locked limit 5 loop
   update private.career_notifications set status='sending',attempts=attempts+1,lease=gen_random_uuid(),claimed_at=now()where id=job.id returning *into job;
   results:=results||jsonb_build_array(jsonb_build_object('id',job.id,'lease',job.lease));
  end loop;return jsonb_build_object('ok',true,'jobs',results);
 elsif p_action='finish'then
  update private.career_notifications set status=case when p_data->>'accepted'='true'then 'accepted'when attempts>=5 then 'failed'else 'queued'end,accepted_at=case when p_data->>'accepted'='true'then now()else null end,next_attempt=now()+interval '5 minutes',lease=null where id=p_id and status='sending'and lease=(p_data->>'lease')::uuid;return '{"ok":true}'::jsonb;
 end if;return '{"ok":false,"code":"invalid_input"}'::jsonb;
end$$;
revoke all on function private.website_careers_service(text,uuid,jsonb)from public,anon,authenticated,console_backend,service_role;
grant execute on function private.website_careers_service(text,uuid,jsonb)to service_role;
create function public.website_careers_service(p_action text,p_id uuid default null,p_data jsonb default '{}')returns jsonb language sql security invoker set search_path=''as $$select private.website_careers_service(p_action,p_id,p_data)$$;
revoke all on function public.website_careers_service(text,uuid,jsonb)from public,anon,authenticated,service_role;
grant execute on function public.website_careers_service(text,uuid,jsonb)to service_role;
-- Schedule only the requested careers notification queue, not customer broadcasts.
create function private.website_careers_tick()returns void language plpgsql security definer set search_path=''as $$declare t text;begin
 if not exists(select 1 from private.career_notifications where(status='queued'and next_attempt<=now()or status='sending'and claimed_at<now()-interval '15 minutes')and attempts<5)then return;end if;
 select token into t from private.website_dispatch_config;
 perform net.http_post(url:='https://ijyjrooarwoafkykvzjp.supabase.co/functions/v1/website-careers',headers:='{"Content-Type":"application/json"}'::jsonb,body:=jsonb_build_object('action','dispatch','token',t),timeout_milliseconds:=15000);
end$$;
revoke all on function private.website_careers_tick()from public,anon,authenticated,service_role,console_backend;
select cron.schedule('vimbre-careers-notifications','*/5 * * * *','select private.website_careers_tick()');

-- Preserve the six existing approved articles and their public addresses.
insert into private.website_posts(slug,draft,published,status,first_published_at,published_updated_at)values
('employee-handover-template','{"slug": "employee-handover-template", "title": "Employee handover template", "description": "A practical employee handover template covering priorities, decisions, deadlines, contacts and access.", "published": "2026-10-30", "author": "Vimbre", "sections": [{"heading": "What a useful employee handover contains", "paragraphs": ["A handover should let another person continue the work without reconstructing it from messages. Start with what needs attention next, then explain the decisions and constraints behind it. A folder of links alone does not tell a colleague what to do.", "Use the template below for a permanent move, a change of role or temporary cover. Replace each bracketed prompt, remove sections that do not apply and give the recipient access to the linked records."]}, {"heading": "Fill it in around real work", "paragraphs": ["List each open item with a current status, next action, named owner and due date. Separate an agreed deadline from an estimate. Record the reason for important decisions and who agreed them so your cover does not accidentally undo them.", "For example: Supplier review — waiting for revised insurance certificate; next step: ask the supplier on Tuesday; owner: [cover]; deadline: [date]. Keep the approved supplier in place until the certificate is checked."]}, {"heading": "Check that someone else can use it", "paragraphs": ["Ask the recipient to open the links and explain back the first two actions. Resolve missing permissions before the handover begins. Agree where new decisions and changes will be recorded, and set a review date.", "Keep passwords and recovery codes out of the document. Request access through your approved administrator or password manager. Limit personal and customer information to what the recipient needs."]}, {"heading": "Keep the handover connected", "paragraphs": ["Use Vimbre to maintain role records, decisions, tasks and reviewed handovers together. The template remains useful on its own: keep one current version and update it when the work changes."]}], "template": "EMPLOYEE HANDOVER\nRole / team: [ ]\nPrepared by: [ ]   Cover / successor: [ ]\nHandover dates: [ ]   Last updated: [ ]\nManager / escalation contact: [ ]\n\n1. START HERE\nPurpose of the role: [ ]\nThree immediate priorities: [ ]\n\n2. OPEN WORK (repeat for each item)\nItem: [ ]\nStatus / last completed step: [ ]\nNext action: [ ]   Owner: [ ]   Due date: [ ]\nSource / document link: [ ]\nBlocker and escalation point: [ ]\n\n3. DECISIONS AND GUARDRAILS\nDecision: [ ]   Reason: [ ]\nAgreed by / date: [ ]   Evidence link: [ ]\nWhat must not change without approval: [ ]\n\n4. ROUTINE WORK\nActivity: [ ]   Frequency / next occurrence: [ ]\nSteps / checklist link: [ ]   Backup owner: [ ]\n\n5. CONTACTS, FILES AND ACCESS\nContact / purpose / approved contact channel: [ ]\nRecord / location / access confirmed: [ ]\nAccess requests still needed (no passwords): [ ]\n\n6. ACCEPTANCE\nRecipient reviewed links on: [ ]\nQuestions / gaps / owner / resolve by: [ ]\nManager sign-off if required: [ ]\nNext review: [ ]", "faq": [{"question": "What should an employee handover include?", "answer": "Include open work, next actions, owners, deadlines, decision reasons, recurring duties, relevant contacts and document links. Confirm access and record any unresolved gaps."}, {"question": "How long should a handover document be?", "answer": "Make the first page a short summary of immediate priorities. Use linked records for detail and include enough instructions for the recipient to carry out the work safely."}]}'::jsonb,'{"slug": "employee-handover-template", "title": "Employee handover template", "description": "A practical employee handover template covering priorities, decisions, deadlines, contacts and access.", "published": "2026-10-30", "author": "Vimbre", "sections": [{"heading": "What a useful employee handover contains", "paragraphs": ["A handover should let another person continue the work without reconstructing it from messages. Start with what needs attention next, then explain the decisions and constraints behind it. A folder of links alone does not tell a colleague what to do.", "Use the template below for a permanent move, a change of role or temporary cover. Replace each bracketed prompt, remove sections that do not apply and give the recipient access to the linked records."]}, {"heading": "Fill it in around real work", "paragraphs": ["List each open item with a current status, next action, named owner and due date. Separate an agreed deadline from an estimate. Record the reason for important decisions and who agreed them so your cover does not accidentally undo them.", "For example: Supplier review — waiting for revised insurance certificate; next step: ask the supplier on Tuesday; owner: [cover]; deadline: [date]. Keep the approved supplier in place until the certificate is checked."]}, {"heading": "Check that someone else can use it", "paragraphs": ["Ask the recipient to open the links and explain back the first two actions. Resolve missing permissions before the handover begins. Agree where new decisions and changes will be recorded, and set a review date.", "Keep passwords and recovery codes out of the document. Request access through your approved administrator or password manager. Limit personal and customer information to what the recipient needs."]}, {"heading": "Keep the handover connected", "paragraphs": ["Use Vimbre to maintain role records, decisions, tasks and reviewed handovers together. The template remains useful on its own: keep one current version and update it when the work changes."]}], "template": "EMPLOYEE HANDOVER\nRole / team: [ ]\nPrepared by: [ ]   Cover / successor: [ ]\nHandover dates: [ ]   Last updated: [ ]\nManager / escalation contact: [ ]\n\n1. START HERE\nPurpose of the role: [ ]\nThree immediate priorities: [ ]\n\n2. OPEN WORK (repeat for each item)\nItem: [ ]\nStatus / last completed step: [ ]\nNext action: [ ]   Owner: [ ]   Due date: [ ]\nSource / document link: [ ]\nBlocker and escalation point: [ ]\n\n3. DECISIONS AND GUARDRAILS\nDecision: [ ]   Reason: [ ]\nAgreed by / date: [ ]   Evidence link: [ ]\nWhat must not change without approval: [ ]\n\n4. ROUTINE WORK\nActivity: [ ]   Frequency / next occurrence: [ ]\nSteps / checklist link: [ ]   Backup owner: [ ]\n\n5. CONTACTS, FILES AND ACCESS\nContact / purpose / approved contact channel: [ ]\nRecord / location / access confirmed: [ ]\nAccess requests still needed (no passwords): [ ]\n\n6. ACCEPTANCE\nRecipient reviewed links on: [ ]\nQuestions / gaps / owner / resolve by: [ ]\nManager sign-off if required: [ ]\nNext review: [ ]", "faq": [{"question": "What should an employee handover include?", "answer": "Include open work, next actions, owners, deadlines, decision reasons, recurring duties, relevant contacts and document links. Confirm access and record any unresolved gaps."}, {"question": "How long should a handover document be?", "answer": "Make the first page a short summary of immediate priorities. Use linked records for detail and include enough instructions for the recipient to carry out the work safely."}]}'::jsonb,'published','2026-10-30'::timestamptz,'2026-10-30'::timestamptz),
('how-to-write-a-handover-document','{"slug": "how-to-write-a-handover-document", "title": "How to write a handover document", "description": "A step-by-step handover writing guide with a fill-in document and a worked example.", "published": "2026-10-30", "author": "Vimbre", "sections": [{"heading": "Start with the recipient’s first day", "paragraphs": ["Write for a person who understands the business but has not followed every conversation. Answer four questions first: what is happening, what happens next, who owns it and why the current approach was chosen.", "Choose a single document owner and a clear date range. Agree whether the document is for temporary cover or a permanent transfer; that changes which decisions the recipient can make."]}, {"heading": "Step 1: collect the current facts", "paragraphs": ["Review your active tasks, recurring duties, recent decisions and upcoming deadlines. Check each item against the actual source. Do not copy an old task list and assume its status is still correct.", "Group the work by project or responsibility. Mark completed work separately so it does not look like a new action."]}, {"heading": "Step 2: turn notes into instructions", "paragraphs": ["Replace vague entries such as “sort reporting” with an action, owner and date. Add where the inputs are stored, the approval needed and the outcome that counts as finished.", "Worked example: “Prepare the monthly report using [source]. Ask [reviewer] to approve the figures by [date], then upload to [location]. The reporting period follows the finance calendar, not the calendar month.”"]}, {"heading": "Step 3: explain the decisions and risks", "paragraphs": ["Describe the reason behind a decision, the people who agreed it and any condition that would make it worth reviewing. List blockers with an escalation contact rather than leaving the recipient to guess.", "For sensitive matters, link to an appropriately restricted record instead of copying its contents into a widely shared handover."]}, {"heading": "Step 4: test and maintain the document", "paragraphs": ["Walk through one task with the recipient. Confirm they can open the files, find the latest version and identify the next deadline. Record questions and assign someone to close each gap.", "Keep one current version. Vimbre can connect the tasks and decisions used in a handover so updates do not depend on remembering which document to edit."]}], "template": "HANDOVER DOCUMENT WORKSHEET\nPurpose: [temporary cover / permanent transfer]\nRole / workstream: [ ]   Dates: [ ]\nDocument owner: [ ]   Recipient: [ ]\nLast checked: [ ]\n\nOVERVIEW (five lines maximum)\nWhat this work achieves: [ ]\nCurrent position: [ ]\nImmediate next step: [ ]\nMost important deadline: [ ]\nMain risk: [ ]\n\nWORK INSTRUCTIONS (repeat)\nOutcome required: [ ]\nInputs and approved file locations: [ ]\nSteps: 1. [ ]  2. [ ]  3. [ ]\nOwner / reviewer: [ ]\nDeadline / time zone: [ ]\nCompletion check: [ ]\nIf blocked, contact: [ ]\n\nDECISION RECORD\nDecision / reason / agreed by / date: [ ]\nEvidence: [ ]   Review trigger: [ ]\n\nRECIPIENT CHECK\nLinks opened: [ ]   Permissions confirmed: [ ]\nExample task walked through: [ ]\nUnresolved question / owner / due date: [ ]\nNext document review: [ ]", "faq": [{"question": "What is the best way to structure a handover document?", "answer": "Begin with immediate priorities, then group open work, routine duties, decisions, risks and access. Finish with a recipient check and unresolved questions."}, {"question": "Who should review a handover?", "answer": "The receiving colleague should review the instructions and links. Involve the manager or relevant approver when ownership, sensitive information or approval authority changes."}]}'::jsonb,'{"slug": "how-to-write-a-handover-document", "title": "How to write a handover document", "description": "A step-by-step handover writing guide with a fill-in document and a worked example.", "published": "2026-10-30", "author": "Vimbre", "sections": [{"heading": "Start with the recipient’s first day", "paragraphs": ["Write for a person who understands the business but has not followed every conversation. Answer four questions first: what is happening, what happens next, who owns it and why the current approach was chosen.", "Choose a single document owner and a clear date range. Agree whether the document is for temporary cover or a permanent transfer; that changes which decisions the recipient can make."]}, {"heading": "Step 1: collect the current facts", "paragraphs": ["Review your active tasks, recurring duties, recent decisions and upcoming deadlines. Check each item against the actual source. Do not copy an old task list and assume its status is still correct.", "Group the work by project or responsibility. Mark completed work separately so it does not look like a new action."]}, {"heading": "Step 2: turn notes into instructions", "paragraphs": ["Replace vague entries such as “sort reporting” with an action, owner and date. Add where the inputs are stored, the approval needed and the outcome that counts as finished.", "Worked example: “Prepare the monthly report using [source]. Ask [reviewer] to approve the figures by [date], then upload to [location]. The reporting period follows the finance calendar, not the calendar month.”"]}, {"heading": "Step 3: explain the decisions and risks", "paragraphs": ["Describe the reason behind a decision, the people who agreed it and any condition that would make it worth reviewing. List blockers with an escalation contact rather than leaving the recipient to guess.", "For sensitive matters, link to an appropriately restricted record instead of copying its contents into a widely shared handover."]}, {"heading": "Step 4: test and maintain the document", "paragraphs": ["Walk through one task with the recipient. Confirm they can open the files, find the latest version and identify the next deadline. Record questions and assign someone to close each gap.", "Keep one current version. Vimbre can connect the tasks and decisions used in a handover so updates do not depend on remembering which document to edit."]}], "template": "HANDOVER DOCUMENT WORKSHEET\nPurpose: [temporary cover / permanent transfer]\nRole / workstream: [ ]   Dates: [ ]\nDocument owner: [ ]   Recipient: [ ]\nLast checked: [ ]\n\nOVERVIEW (five lines maximum)\nWhat this work achieves: [ ]\nCurrent position: [ ]\nImmediate next step: [ ]\nMost important deadline: [ ]\nMain risk: [ ]\n\nWORK INSTRUCTIONS (repeat)\nOutcome required: [ ]\nInputs and approved file locations: [ ]\nSteps: 1. [ ]  2. [ ]  3. [ ]\nOwner / reviewer: [ ]\nDeadline / time zone: [ ]\nCompletion check: [ ]\nIf blocked, contact: [ ]\n\nDECISION RECORD\nDecision / reason / agreed by / date: [ ]\nEvidence: [ ]   Review trigger: [ ]\n\nRECIPIENT CHECK\nLinks opened: [ ]   Permissions confirmed: [ ]\nExample task walked through: [ ]\nUnresolved question / owner / due date: [ ]\nNext document review: [ ]", "faq": [{"question": "What is the best way to structure a handover document?", "answer": "Begin with immediate priorities, then group open work, routine duties, decisions, risks and access. Finish with a recipient check and unresolved questions."}, {"question": "Who should review a handover?", "answer": "The receiving colleague should review the instructions and links. Involve the manager or relevant approver when ownership, sensitive information or approval authority changes."}]}'::jsonb,'published','2026-10-30'::timestamptz,'2026-10-30'::timestamptz),
('handover-checklist-for-managers','{"slug": "handover-checklist-for-managers", "title": "Handover checklist for managers", "description": "A manager’s checklist for ownership, access, risk, acceptance and follow-up during a team handover.", "published": "2026-10-30", "author": "Vimbre", "sections": [{"heading": "Manage the transfer, not just the document", "paragraphs": ["A completed document does not by itself mean responsibility has transferred. A manager needs to confirm who owns each commitment, whether the cover person has capacity and what decisions require approval.", "Use this checklist before leave, a role change or an employee departure. Set the handover scope first and agree what will pause rather than silently allocating everything to one colleague."]}, {"heading": "Before the transfer", "paragraphs": ["Check the next two weeks of deadlines, key customer or supplier commitments and routine work that could otherwise stop. Name a backup for time-sensitive work. Review which tasks can be deferred with the relevant stakeholder.", "Verify access through normal approval channels. Do not ask the outgoing person to share a password or use a personal account as a workaround."]}, {"heading": "At the handover review", "paragraphs": ["Ask the recipient to describe the next action for each critical item. Review decision reasons and escalation thresholds. Distinguish outstanding questions from agreed instructions and assign an owner and date to resolve each question.", "For example, a payment deadline may need cover immediately while a research task can wait. Document the decision to defer work so it does not become an invisible missed commitment."]}, {"heading": "After the transfer", "paragraphs": ["Check the first completed cycle of important routine work. Review new blockers with the cover person and rebalance workload if required. When temporary cover ends, explicitly take back ownership and review what changed.", "Vimbre’s reviewed handovers can support this process alongside connected role records and tasks. Keep the acceptance check even when the document is generated from existing records."]}], "template": "MANAGER HANDOVER CHECKLIST\nEmployee / role: [ ]   Recipient: [ ]\nManager: [ ]   Transfer date: [ ]\n\nSCOPE AND CAPACITY\n[ ] Coverage dates and responsibilities agreed\n[ ] Recipient capacity checked\n[ ] Work to pause agreed with stakeholders\n[ ] Backup and escalation owner named\n\nWORK AND RISK\n[ ] Critical deadlines have an owner\n[ ] Customer / supplier commitments recorded\n[ ] Recurring duties have instructions and next dates\n[ ] Decision reasons and approval limits documented\n[ ] Known risks have mitigation and escalation steps\n\nACCESS AND RECORDS\n[ ] Recipient can open the current files\n[ ] Approved access requests completed\n[ ] Sensitive information shared only where needed\n[ ] No passwords or recovery codes in handover notes\n\nACCEPTANCE\n[ ] Recipient walked through critical items\n[ ] Open question / owner / due date recorded\n[ ] Required approvals completed\n[ ] Relevant stakeholders informed\n\nFOLLOW-UP\nFirst review date: [ ]\nTemporary cover take-back date: [ ]\nOutstanding gap / owner / resolve by: [ ]\nManager acceptance / date: [ ]", "faq": [{"question": "What should a manager check before accepting a handover?", "answer": "Check ownership, recipient capacity, deadlines, access, risks and unresolved questions. Confirm that the recipient can carry out the next critical actions."}, {"question": "Should every handover need manager approval?", "answer": "Use the approval process appropriate to your company and the risk involved. Make approval explicit where responsibilities, access or important commitments change."}]}'::jsonb,'{"slug": "handover-checklist-for-managers", "title": "Handover checklist for managers", "description": "A manager’s checklist for ownership, access, risk, acceptance and follow-up during a team handover.", "published": "2026-10-30", "author": "Vimbre", "sections": [{"heading": "Manage the transfer, not just the document", "paragraphs": ["A completed document does not by itself mean responsibility has transferred. A manager needs to confirm who owns each commitment, whether the cover person has capacity and what decisions require approval.", "Use this checklist before leave, a role change or an employee departure. Set the handover scope first and agree what will pause rather than silently allocating everything to one colleague."]}, {"heading": "Before the transfer", "paragraphs": ["Check the next two weeks of deadlines, key customer or supplier commitments and routine work that could otherwise stop. Name a backup for time-sensitive work. Review which tasks can be deferred with the relevant stakeholder.", "Verify access through normal approval channels. Do not ask the outgoing person to share a password or use a personal account as a workaround."]}, {"heading": "At the handover review", "paragraphs": ["Ask the recipient to describe the next action for each critical item. Review decision reasons and escalation thresholds. Distinguish outstanding questions from agreed instructions and assign an owner and date to resolve each question.", "For example, a payment deadline may need cover immediately while a research task can wait. Document the decision to defer work so it does not become an invisible missed commitment."]}, {"heading": "After the transfer", "paragraphs": ["Check the first completed cycle of important routine work. Review new blockers with the cover person and rebalance workload if required. When temporary cover ends, explicitly take back ownership and review what changed.", "Vimbre’s reviewed handovers can support this process alongside connected role records and tasks. Keep the acceptance check even when the document is generated from existing records."]}], "template": "MANAGER HANDOVER CHECKLIST\nEmployee / role: [ ]   Recipient: [ ]\nManager: [ ]   Transfer date: [ ]\n\nSCOPE AND CAPACITY\n[ ] Coverage dates and responsibilities agreed\n[ ] Recipient capacity checked\n[ ] Work to pause agreed with stakeholders\n[ ] Backup and escalation owner named\n\nWORK AND RISK\n[ ] Critical deadlines have an owner\n[ ] Customer / supplier commitments recorded\n[ ] Recurring duties have instructions and next dates\n[ ] Decision reasons and approval limits documented\n[ ] Known risks have mitigation and escalation steps\n\nACCESS AND RECORDS\n[ ] Recipient can open the current files\n[ ] Approved access requests completed\n[ ] Sensitive information shared only where needed\n[ ] No passwords or recovery codes in handover notes\n\nACCEPTANCE\n[ ] Recipient walked through critical items\n[ ] Open question / owner / due date recorded\n[ ] Required approvals completed\n[ ] Relevant stakeholders informed\n\nFOLLOW-UP\nFirst review date: [ ]\nTemporary cover take-back date: [ ]\nOutstanding gap / owner / resolve by: [ ]\nManager acceptance / date: [ ]", "faq": [{"question": "What should a manager check before accepting a handover?", "answer": "Check ownership, recipient capacity, deadlines, access, risks and unresolved questions. Confirm that the recipient can carry out the next critical actions."}, {"question": "Should every handover need manager approval?", "answer": "Use the approval process appropriate to your company and the risk involved. Make approval explicit where responsibilities, access or important commitments change."}]}'::jsonb,'published','2026-10-30'::timestamptz,'2026-10-30'::timestamptz),
('what-to-do-when-an-employee-leaves-suddenly','{"slug": "what-to-do-when-an-employee-leaves-suddenly", "title": "What to do when an employee leaves suddenly", "description": "A practical continuity plan and triage template for an unexpected employee departure.", "published": "2026-10-30", "author": "Vimbre", "sections": [{"heading": "Stabilise the work before rebuilding the history", "paragraphs": ["An unexpected departure creates two immediate problems: keeping important work moving and establishing what is actually known. Appoint a continuity owner and record verified facts separately from assumptions.", "Coordinate with HR, IT and the appropriate manager using your company’s approved departure process. The continuity checklist below covers operational work; it does not replace employment advice or your organisation’s access and retention policies."]}, {"heading": "First: identify urgent commitments", "paragraphs": ["Check the shared calendar, authorised task records and approved team files for deadlines, customer commitments and recurring duties. Ask the relevant stakeholders to confirm the next action and consequence of delay.", "Create one triage list with urgency, a temporary owner and the next check-in. Do not assume that the absence of a task in a system means no commitment exists."]}, {"heading": "Next: preserve access and evidence appropriately", "paragraphs": ["Ask authorised administrators to manage account access, business records and any retention requirements. Use approved shared access rather than signing in with the departing employee’s credentials.", "Avoid copying private communications into a general handover. Limit access to people who need it, and record the source of recovered work context so colleagues can distinguish evidence from recollection."]}, {"heading": "Then: reconstruct decisions and allocate cover", "paragraphs": ["For each priority, find the most recent agreed decision, the reason and the stakeholder who can confirm it. Mark missing context as a gap with a named owner. Agree which work can pause while the team recovers.", "Review the triage list daily until urgent work has stable ownership. Once continuity is restored, update role records and recurring duties. Vimbre can help keep this context connected before the next absence."]}], "template": "UNEXPECTED DEPARTURE — CONTINUITY TRIAGE\nRole / team: [ ]   Continuity owner: [ ]\nDate / time prepared: [ ]\nHR contact: [ ]   Authorised IT contact: [ ]\n\nIMMEDIATE COMMITMENTS (repeat)\nCommitment / deadline: [ ]\nImpact if missed: [ ]\nVerified source / person confirming: [ ]\nTemporary owner / backup: [ ]\nNext action / check-in: [ ]\n\nACCESS AND RECORDS\nSystem / business record needed: [ ]\nAuthorised administrator: [ ]\nApproved access / retention action: [ ]\nStatus / completion date: [ ]\n\nCONTEXT GAPS\nQuestion: [ ]\nKnown facts and source: [ ]\nUnverified assumption (label clearly): [ ]\nWho can confirm / by when: [ ]\n\nCOVER DECISIONS\nWork continuing / owner: [ ]\nWork paused / stakeholder agreement: [ ]\nEscalation threshold / contact: [ ]\n\nRECOVERY REVIEW\nNext review date: [ ]\nRemaining operational risk: [ ]\nRole records / routine instructions updated by: [ ]", "faq": [{"question": "What should we do first when an employee leaves unexpectedly?", "answer": "Appoint a continuity owner, identify urgent commitments and coordinate with HR and authorised IT administrators. Separate verified information from assumptions and allocate temporary task owners."}, {"question": "How can we recover missing work context?", "answer": "Review authorised business records and ask relevant stakeholders to confirm decisions and next steps. Record the source, flag uncertainty and give every unresolved gap an owner."}]}'::jsonb,'{"slug": "what-to-do-when-an-employee-leaves-suddenly", "title": "What to do when an employee leaves suddenly", "description": "A practical continuity plan and triage template for an unexpected employee departure.", "published": "2026-10-30", "author": "Vimbre", "sections": [{"heading": "Stabilise the work before rebuilding the history", "paragraphs": ["An unexpected departure creates two immediate problems: keeping important work moving and establishing what is actually known. Appoint a continuity owner and record verified facts separately from assumptions.", "Coordinate with HR, IT and the appropriate manager using your company’s approved departure process. The continuity checklist below covers operational work; it does not replace employment advice or your organisation’s access and retention policies."]}, {"heading": "First: identify urgent commitments", "paragraphs": ["Check the shared calendar, authorised task records and approved team files for deadlines, customer commitments and recurring duties. Ask the relevant stakeholders to confirm the next action and consequence of delay.", "Create one triage list with urgency, a temporary owner and the next check-in. Do not assume that the absence of a task in a system means no commitment exists."]}, {"heading": "Next: preserve access and evidence appropriately", "paragraphs": ["Ask authorised administrators to manage account access, business records and any retention requirements. Use approved shared access rather than signing in with the departing employee’s credentials.", "Avoid copying private communications into a general handover. Limit access to people who need it, and record the source of recovered work context so colleagues can distinguish evidence from recollection."]}, {"heading": "Then: reconstruct decisions and allocate cover", "paragraphs": ["For each priority, find the most recent agreed decision, the reason and the stakeholder who can confirm it. Mark missing context as a gap with a named owner. Agree which work can pause while the team recovers.", "Review the triage list daily until urgent work has stable ownership. Once continuity is restored, update role records and recurring duties. Vimbre can help keep this context connected before the next absence."]}], "template": "UNEXPECTED DEPARTURE — CONTINUITY TRIAGE\nRole / team: [ ]   Continuity owner: [ ]\nDate / time prepared: [ ]\nHR contact: [ ]   Authorised IT contact: [ ]\n\nIMMEDIATE COMMITMENTS (repeat)\nCommitment / deadline: [ ]\nImpact if missed: [ ]\nVerified source / person confirming: [ ]\nTemporary owner / backup: [ ]\nNext action / check-in: [ ]\n\nACCESS AND RECORDS\nSystem / business record needed: [ ]\nAuthorised administrator: [ ]\nApproved access / retention action: [ ]\nStatus / completion date: [ ]\n\nCONTEXT GAPS\nQuestion: [ ]\nKnown facts and source: [ ]\nUnverified assumption (label clearly): [ ]\nWho can confirm / by when: [ ]\n\nCOVER DECISIONS\nWork continuing / owner: [ ]\nWork paused / stakeholder agreement: [ ]\nEscalation threshold / contact: [ ]\n\nRECOVERY REVIEW\nNext review date: [ ]\nRemaining operational risk: [ ]\nRole records / routine instructions updated by: [ ]", "faq": [{"question": "What should we do first when an employee leaves unexpectedly?", "answer": "Appoint a continuity owner, identify urgent commitments and coordinate with HR and authorised IT administrators. Separate verified information from assumptions and allocate temporary task owners."}, {"question": "How can we recover missing work context?", "answer": "Review authorised business records and ask relevant stakeholders to confirm decisions and next steps. Record the source, flag uncertainty and give every unresolved gap an owner."}]}'::jsonb,'published','2026-10-30'::timestamptz,'2026-10-30'::timestamptz),
('annual-leave-handover-notes','{"slug": "annual-leave-handover-notes", "title": "Annual leave handover notes", "description": "A concise annual leave handover template for dates, cover, recurring work and a smooth return.", "published": "2026-10-30", "author": "Vimbre", "sections": [{"heading": "Make cover easy to pick up", "paragraphs": ["Annual leave notes should explain what needs attention while you are away, what can wait and who can make decisions. Begin with the dates and cover arrangement rather than a history of every project.", "Agree the cover with your manager and colleague before sharing the notes. State the return date and time zone where relevant. Avoid promising availability while on leave unless that has been explicitly agreed."]}, {"heading": "Prioritise the work that falls inside your leave", "paragraphs": ["Check deadlines and routine duties for the actual absence period. Give each item a next action, owner and source link. Include the expected response if a dependency slips.", "Example: “The weekly supplier check is due Thursday. Use [checklist], log exceptions in [record], and escalate a missing certificate to [manager]. The monthly review can wait until I return.”"]}, {"heading": "Set boundaries and escalation routes", "paragraphs": ["Explain which decisions your cover can make and which need approval. List a manager or backup contact for urgent issues. Confirm that the cover person can access the records before your leave starts.", "Keep the notes in the normal shared work location. Do not include passwords, personal travel details or customer information that the cover person does not need."]}, {"heading": "Close the loop on return", "paragraphs": ["Ask your cover to record what changed, new decisions and any work still outstanding. Review the notes together and explicitly take back ongoing tasks.", "Vimbre can connect temporary cover, tasks and decision context. Whether you use Vimbre or a document, the return update is part of the handover, not an optional extra."]}], "template": "ANNUAL LEAVE HANDOVER\nName / role: [ ]\nAway from: [ ]   Return date / time zone: [ ]\nPrimary cover: [ ]   Backup: [ ]\nManager / urgent escalation: [ ]\nLast updated: [ ]\n\nDURING MY LEAVE (repeat)\nTask / recurring duty: [ ]\nDue date: [ ]   Cover owner: [ ]\nCurrent status: [ ]\nNext action / instructions: [ ]\nSource / file link: [ ]\nIf blocked: [ ]\n\nCAN WAIT UNTIL I RETURN\nItem / reason / next review date: [ ]\n\nDECISIONS AND LIMITS\nCover can decide: [ ]\nApproval needed for: [ ]\nExisting decision / reason / evidence: [ ]\n\nBEFORE LEAVE\n[ ] Cover agreed and capacity confirmed\n[ ] Links and permissions tested\n[ ] Stakeholders told who to contact\n[ ] Routine deadlines checked\n\nCOVER RETURN NOTES\nWhat changed / date / record link: [ ]\nNew decision / agreed by / reason: [ ]\nOutstanding task / owner / due date: [ ]\nOwnership returned on: [ ]", "faq": [{"question": "What should annual leave handover notes include?", "answer": "Include absence and return dates, the cover person, work due during leave, instructions, access links, escalation contacts and decisions that require approval."}, {"question": "Should handover notes include tasks that can wait?", "answer": "Yes. Label work that can wait and agree its next review date so the cover person can focus on the commitments that fall during the absence."}]}'::jsonb,'{"slug": "annual-leave-handover-notes", "title": "Annual leave handover notes", "description": "A concise annual leave handover template for dates, cover, recurring work and a smooth return.", "published": "2026-10-30", "author": "Vimbre", "sections": [{"heading": "Make cover easy to pick up", "paragraphs": ["Annual leave notes should explain what needs attention while you are away, what can wait and who can make decisions. Begin with the dates and cover arrangement rather than a history of every project.", "Agree the cover with your manager and colleague before sharing the notes. State the return date and time zone where relevant. Avoid promising availability while on leave unless that has been explicitly agreed."]}, {"heading": "Prioritise the work that falls inside your leave", "paragraphs": ["Check deadlines and routine duties for the actual absence period. Give each item a next action, owner and source link. Include the expected response if a dependency slips.", "Example: “The weekly supplier check is due Thursday. Use [checklist], log exceptions in [record], and escalate a missing certificate to [manager]. The monthly review can wait until I return.”"]}, {"heading": "Set boundaries and escalation routes", "paragraphs": ["Explain which decisions your cover can make and which need approval. List a manager or backup contact for urgent issues. Confirm that the cover person can access the records before your leave starts.", "Keep the notes in the normal shared work location. Do not include passwords, personal travel details or customer information that the cover person does not need."]}, {"heading": "Close the loop on return", "paragraphs": ["Ask your cover to record what changed, new decisions and any work still outstanding. Review the notes together and explicitly take back ongoing tasks.", "Vimbre can connect temporary cover, tasks and decision context. Whether you use Vimbre or a document, the return update is part of the handover, not an optional extra."]}], "template": "ANNUAL LEAVE HANDOVER\nName / role: [ ]\nAway from: [ ]   Return date / time zone: [ ]\nPrimary cover: [ ]   Backup: [ ]\nManager / urgent escalation: [ ]\nLast updated: [ ]\n\nDURING MY LEAVE (repeat)\nTask / recurring duty: [ ]\nDue date: [ ]   Cover owner: [ ]\nCurrent status: [ ]\nNext action / instructions: [ ]\nSource / file link: [ ]\nIf blocked: [ ]\n\nCAN WAIT UNTIL I RETURN\nItem / reason / next review date: [ ]\n\nDECISIONS AND LIMITS\nCover can decide: [ ]\nApproval needed for: [ ]\nExisting decision / reason / evidence: [ ]\n\nBEFORE LEAVE\n[ ] Cover agreed and capacity confirmed\n[ ] Links and permissions tested\n[ ] Stakeholders told who to contact\n[ ] Routine deadlines checked\n\nCOVER RETURN NOTES\nWhat changed / date / record link: [ ]\nNew decision / agreed by / reason: [ ]\nOutstanding task / owner / due date: [ ]\nOwnership returned on: [ ]", "faq": [{"question": "What should annual leave handover notes include?", "answer": "Include absence and return dates, the cover person, work due during leave, instructions, access links, escalation contacts and decisions that require approval."}, {"question": "Should handover notes include tasks that can wait?", "answer": "Yes. Label work that can wait and agree its next review date so the cover person can focus on the commitments that fall during the absence."}]}'::jsonb,'published','2026-10-30'::timestamptz,'2026-10-30'::timestamptz),
('knowledge-loss-when-staff-leave','{"slug": "knowledge-loss-when-staff-leave", "title": "Knowledge loss when staff leave", "description": "A practical knowledge risk register and capture plan for decisions, recurring work and key relationships.", "published": "2026-10-30", "author": "Vimbre", "sections": [{"heading": "Find the knowledge that only one person holds", "paragraphs": ["Knowledge loss is not just a missing file. Teams can lose the reason a decision was made, the warning signs in a process, the history of a relationship or the sequence needed to finish routine work.", "Start with work that would stall if its owner were unavailable tomorrow. Ask what another colleague would need to understand and carry it out without relying on that person’s memory."]}, {"heading": "Build a small knowledge risk register", "paragraphs": ["For each important responsibility, record the current owner, the consequence of losing the context, where the instructions live and whether someone else has tested them. Prioritise high-impact work with no verified backup.", "For example: “Supplier renewal — only one person knows the approval sequence; renewal is next month; capture the steps and decision history this week, then ask the backup to walk through them.”"]}, {"heading": "Capture reasons as well as steps", "paragraphs": ["A checklist explains how to act, but a decision record explains when to change course. Record the decision, reason, who agreed it, date, supporting evidence and the condition that should trigger a review.", "For relationships, document the business purpose and approved contact route. Keep personal commentary and unnecessary sensitive details out of shared records."]}, {"heading": "Test the backup before you need it", "paragraphs": ["Ask the backup to complete a representative task using the record. Note where they needed help and improve those instructions. Set a review date tied to a work cycle or a material change.", "Vimbre keeps discussions, decisions and actions connected with role records and handovers. That can reduce the effort of rebuilding context, but a named owner and regular review still matter."]}], "template": "KNOWLEDGE CONTINUITY REGISTER\nTeam: [ ]   Register owner: [ ]\nReview date: [ ]\n\nKNOWLEDGE RISK (repeat)\nResponsibility / process: [ ]\nCurrent knowledge owner: [ ]\nBusiness impact if unavailable: [ ]\nNext critical date: [ ]\nRisk priority / reason: [ ]\nExisting record / location: [ ]\nNamed backup: [ ]\nLast backup walkthrough / result: [ ]\nGap to close / owner / due date: [ ]\n\nDECISION CAPTURE\nDecision: [ ]   Reason: [ ]\nAgreed by / date: [ ]\nEvidence / source link: [ ]\nWhen to review: [ ]\n\nPROCESS CAPTURE\nInputs / location: [ ]\nSteps / approval points: [ ]\nWarning signs / escalation route: [ ]\nOutput / completion check: [ ]\n\nCONTINUITY CHECK\n[ ] Backup can find the latest record\n[ ] Access tested through approved channels\n[ ] Representative task completed from instructions\n[ ] Missing context assigned to an owner\nNext review / owner: [ ]", "faq": [{"question": "What knowledge is most at risk when staff leave?", "answer": "Decision reasons, undocumented process steps, upcoming commitments and relationship history are often vulnerable when only one person can explain them. Start with responsibilities that have no tested backup."}, {"question": "How do we check whether knowledge has really transferred?", "answer": "Ask another person to find the current record and carry out a representative task. Record where they need help, improve the instructions and repeat the check."}]}'::jsonb,'{"slug": "knowledge-loss-when-staff-leave", "title": "Knowledge loss when staff leave", "description": "A practical knowledge risk register and capture plan for decisions, recurring work and key relationships.", "published": "2026-10-30", "author": "Vimbre", "sections": [{"heading": "Find the knowledge that only one person holds", "paragraphs": ["Knowledge loss is not just a missing file. Teams can lose the reason a decision was made, the warning signs in a process, the history of a relationship or the sequence needed to finish routine work.", "Start with work that would stall if its owner were unavailable tomorrow. Ask what another colleague would need to understand and carry it out without relying on that person’s memory."]}, {"heading": "Build a small knowledge risk register", "paragraphs": ["For each important responsibility, record the current owner, the consequence of losing the context, where the instructions live and whether someone else has tested them. Prioritise high-impact work with no verified backup.", "For example: “Supplier renewal — only one person knows the approval sequence; renewal is next month; capture the steps and decision history this week, then ask the backup to walk through them.”"]}, {"heading": "Capture reasons as well as steps", "paragraphs": ["A checklist explains how to act, but a decision record explains when to change course. Record the decision, reason, who agreed it, date, supporting evidence and the condition that should trigger a review.", "For relationships, document the business purpose and approved contact route. Keep personal commentary and unnecessary sensitive details out of shared records."]}, {"heading": "Test the backup before you need it", "paragraphs": ["Ask the backup to complete a representative task using the record. Note where they needed help and improve those instructions. Set a review date tied to a work cycle or a material change.", "Vimbre keeps discussions, decisions and actions connected with role records and handovers. That can reduce the effort of rebuilding context, but a named owner and regular review still matter."]}], "template": "KNOWLEDGE CONTINUITY REGISTER\nTeam: [ ]   Register owner: [ ]\nReview date: [ ]\n\nKNOWLEDGE RISK (repeat)\nResponsibility / process: [ ]\nCurrent knowledge owner: [ ]\nBusiness impact if unavailable: [ ]\nNext critical date: [ ]\nRisk priority / reason: [ ]\nExisting record / location: [ ]\nNamed backup: [ ]\nLast backup walkthrough / result: [ ]\nGap to close / owner / due date: [ ]\n\nDECISION CAPTURE\nDecision: [ ]   Reason: [ ]\nAgreed by / date: [ ]\nEvidence / source link: [ ]\nWhen to review: [ ]\n\nPROCESS CAPTURE\nInputs / location: [ ]\nSteps / approval points: [ ]\nWarning signs / escalation route: [ ]\nOutput / completion check: [ ]\n\nCONTINUITY CHECK\n[ ] Backup can find the latest record\n[ ] Access tested through approved channels\n[ ] Representative task completed from instructions\n[ ] Missing context assigned to an owner\nNext review / owner: [ ]", "faq": [{"question": "What knowledge is most at risk when staff leave?", "answer": "Decision reasons, undocumented process steps, upcoming commitments and relationship history are often vulnerable when only one person can explain them. Start with responsibilities that have no tested backup."}, {"question": "How do we check whether knowledge has really transferred?", "answer": "Ask another person to find the current record and carry out a representative task. Record where they need help, improve the instructions and repeat the check."}]}'::jsonb,'published','2026-10-30'::timestamptz,'2026-10-30'::timestamptz)
